219	      // it was.
220	      if (matchesFilter) {
221	        emit(
222	          MeusRegistrosLoaded(
223	            entries: [entry],
224	            nextCursor: null,
225	            pendingWrites: _visiblePendingWrites,
226	          ),
227	        );
228	      }
